file.content:
                STATUS_CONFIRMED
                if block.status == STATUS_CONFIRMED
                else STATUS_PENDING
            )
    if tx_id in self.store.pending:
        return STATUS_PENDING
    return None

def get_account_sequence(self, account: object) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/sequence — the account's nonce stream.

    Returns ``{account, next_sequence, pending_sequences,
    confirmed_sequences}``; the two arrays list ``{nonce, tx_id}`` pairs
    ascending by nonce. An account that has never sent a sequenced
    transfer (a "stranger") still answers 200 with next_sequence 0 and
    empty arrays. A non-string or empty account is 400 input.
    """
    if not isinstance(account, str) or not account:
        return 400, {"error": "input"}
    with self.store.lock:
        state = self.store.sequences.get(account)
        if state is None:
            return 200, {
                "account": account,
                "next_sequence": 0,
                "pending_sequences": [],
                "confirmed_sequences": [],
            }
        confirmed = [
            {"nonce": nonce, "tx_id": state["confirmed"][nonce]}
            for nonce in sorted(state["confirmed"])
        ]
        reserved = [
            {"nonce": nonce, "tx_id": state["pending"][nonce]}
            for nonce in sorted(state["pending"])
        ]
        return 200, {
            "account": account,
            "next_sequence": self.store.sequence_next(state),
            "pending_sequences": reserved,
            "confirmed_sequences": confirmed,
        }

def get_transaction(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id} — one transaction receipt.

    The lookup covers the canonical chain and the mempool only; candidate
    forks are never exposed. A ``tx_id`` that is not exactly 64 lowercase
    hex characters, or one nothing holds, returns 404.

    A mempool transaction is reported ``pending`` with ``height``,
    ``block_hash`` and ``index`` all null. A transaction packed into the
    unconfirmed tip block is ``pending`` too, anchored at that block with
    its 0-based in-block index. A transaction in a confirmed block is
    ``confirmed``. Every receipt is built from the stored signed
    transaction: the id is recomputed from its canonical message (never
    taken from an index or a fork-side cache) and the fields are strictly
    re-typed (non-empty strings, a positive non-boolean integer amount),
    so adoption, rollback and restart can only ever surface the current
    canonical/pending state.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        # Canonical chain first: confirmed blocks, then at most one
        # pending tip. The stored signed transaction is the sole source
        # for the receipt, and its id is recomputed rather than trusted
        # from any lookup key.
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id != tx_id:
                    continue
                if not self._is_receipt_tx_well_typed(tx):
                    return 404, {"error": "transaction not found"}
                status = (
                    STATUS_CONFIRMED
                    if block.status == STATUS_CONFIRMED
                    else STATUS_PENDING
                )
                return 200, self._transaction_receipt(
                    tx, status, block.height, block.block_hash, index
                )
        # Still unpacked in the mempool.
        tx = self.store.pending.get(tx_id)
        if tx is not None:
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
            return 200, self._transaction_receipt(
                tx, STATUS_PENDING, None, None, None
            )
        return 404, {"error": "transaction not found"}

@staticmethod
def _is_receipt_tx_well_typed(tx: Transaction) -> bool:
    """Strict receipt-time type check of a stored signed transaction.

    Every stored transaction already passed these checks at submission
    (and again during snapshot recovery); the re-check guarantees a
    receipt can never serialize a value that violates the response
    contract, even if an in-memory invariant were broken.
    """
    return (
        isinstance(tx.sender, str)
        and bool(tx.sender)
        and isinstance(tx.recipient, str)
        and bool(tx.recipient)
        and isinstance(tx.amount, int)
        and not isinstance(tx.amount, bool)
        and tx.amount > 0
        and isinstance(tx.signature, str)
        and bool(tx.signature)
        and (
            tx.nonce is None
            or (isinstance(tx.nonce, int) and not isinstance(tx.nonce, bool) and tx.nonce >= 0)
        )
    )

@staticmethod
def _transaction_receipt(
    tx: Transaction,
    status: str,
    height: int | None,
    block_hash: str | None,
    index: int | None,
) -> dict:
    """The fixed nine-field receipt shape for legacy transfers.

    A sequenced transfer appends one further field, ``nonce`` (its
    non-negative sequence number), after ``index``; a legacy transfer
    keeps the exact nine-field document unchanged.
    """
    receipt = {
        "tx_id": tx.tx_id,
        "from": tx.sender,
        "to": tx.recipient,
        "amount": tx.amount,
        "signature": tx.signature,
        "status": status,
        "height": height,
        "block_hash": block_hash,
        "index": index,
    }
    if tx.nonce is not None:
        receipt["nonce"] = tx.nonce
    return receipt

# At most this many distinct ids are accepted by one batch receipt query.
RECEIPTS_MAX_TX_IDS = 200

def get_transaction_receipts(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/receipts — a batch of ordinary transaction
    receipts against one persisted ledger state.

    The body must be a JSON object containing exactly the ``tx_ids``
    key: an array of between one and ``RECEIPTS_MAX_TX_IDS`` distinct
    strings, each exactly 64 lowercase hex characters. Every other
    shape — a non-object body, a missing or extra key, a non-array or
    out-of-range array, a malformed element, or a duplicate — is 400
    ``{"error": "input"}`` and never reaches the lookup; a well-formed
    but unknown id is not an input error.

    A legal batch is always answered 200 with the fixed key order
    ``items, total``: ``total`` equals the number of requested ids and
    ``items`` keeps the request order exactly. Each item has the fixed
    key order ``tx_id, receipt, error``: a hit carries the exact
    :meth:`get_transaction` receipt (same fields, types and meaning)
    with ``error`` null; a miss carries a null ``receipt`` and
    ``not_found`` — an id held only by a candidate fork, or retired by a
    rollback or fork adoption, is a miss. The whole batch is resolved
    under one store lock, so concurrent commits, confirms, rollbacks or
    fork adoptions can never make one response straddle two ledger
    states; the query is read-only.
    """
    bad_input = 400, {"error": "input"}
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return bad_input
    tx_ids = payload["tx_ids"]
    if not isinstance(tx_ids, list) or not (
        1 <= len(tx_ids) <= self.RECEIPTS_MAX_TX_IDS
    ):
        return bad_input
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids):
        return bad_input
    if len(set(tx_ids)) != len(tx_ids):
        return bad_input

    with self.store.lock:
        # Resolve every id against one persisted-state snapshot: the
        # canonical chain first (confirmed blocks, then at most one
        # pending tip), then the mempool. Candidate forks are never
        # iterated, and receipts are rebuilt from the stored signed
        # transactions exactly as for the single-receipt endpoint.
        requested = set(tx_ids)
        located: dict[str, tuple[str, int, str, int, Transaction]] = {}
        for block in self.store.chain:
            status = (
                STATUS_CONFIRMED
                if block.status == STATUS_CONFIRMED
                else STATUS_PENDING
            )
            for index, tx in enumerate(block.transactions):
                if tx.tx_id in requested and tx.tx_id not in located:
                    located[tx.tx_id] = (
                        status,
                        block.height,
                        block.block_hash,
                        index,
                        tx,
                    )
        items: list[dict] = []
        for tx_id in tx_ids:
            match = located.get(tx_id)
            if match is None:
                tx = self.store.pending.get(tx_id)
                if tx is None:
                    items.append(
                        {"tx_id": tx_id, "receipt": None, "error": "not_found"}
                    )
                    continue
                match = (STATUS_PENDING, None, None, None, tx)
            status, height, block_hash, index, tx = match
            if not self._is_receipt_tx_well_typed(tx):
                # A stored value violating the receipt contract is
                # treated as absent rather than serialized, exactly as
                # the single-receipt endpoint's 404.
                items.append(
                    {"tx_id": tx_id, "receipt": None, "error": "not_found"}
                )
                continue
            items.append(
                {
                    "tx_id": tx_id,
                    "receipt": self._transaction_receipt(
                        tx, status, height, block_hash, index
                    ),
                    "error": None,
                }
            )
        return 200, {"items": items, "total": len(items)}

def get_finalized_receipt(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id}/finalized-receipt — an offline-verifiable
    finalized transaction receipt.

    Lookup and typing rules mirror :meth:`get_transaction`: a ``tx_id``
    that is not exactly 64 lowercase hex characters, or one nothing
    holds on the canonical chain (the mempool and candidate forks are
    not matches here), returns 404. A transaction still in the mempool
    or packed into the unconfirmed pending tip is not final and returns
    409.

    On success the whole document is snapshotted under one store lock
    together with the current audit signer, so the receipt, proof,
    headers and finality credential can never mix chain states. The
    body has the fixed key order ``receipt, proof, headers, finality``:
    ``receipt`` is the fixed nine-field receipt with ``status``
    confirmed; ``proof`` is the single-transaction Merkle proof of
    ``GET /v1/blocks/{height}/proof/{tx_id}``; ``headers`` run from the
    transaction's own confirmed block up to and including the highest
    confirmed block in ascending height, each item in the signed header
    page's five-field shape (every item confirmed); and ``finality`` is
    exactly the ``GET /v1/chain/finality`` document, whose
    ``finalized`` names that last header.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    from . import light_client

    with self.store.lock:
        matched: tuple[Block, int, Transaction] | None = None
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id == tx_id:
                    matched = (block, index, tx)
                    break
            if matched is not None:
                break
        if matched is None:
            # Neither the canonical chain nor (below) the mempool holds
            # the id; candidate forks are never exposed.
            if tx_id in self.store.pending:
                return 409, {"error": "transaction is not confirmed"}
            return 404, {"error": "transaction not found"}
        block, index, tx = matched
        if not self._is_receipt_tx_well_typed(tx):
            return 404, {"error": "transaction not found"}
        if block.status != STATUS_CONFIRMED:
            # A packed-but-unconfirmed transaction can only sit in the
            # pending chain tip.
            return 409, {"error": "transaction is not confirmed"}

        tx_ids = [candidate.tx_id for candidate in block.transactions]
        proof = {
            "height": block.height,
            "tx_id": tx.tx_id,
            "index": index,
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "siblings": crypto.merkle_proof(tx_ids, index),
        }

        finalized_block = next(
            candidate
            for candidate in reversed(self.store.chain)
            if candidate.status == STATUS_CONFIRMED
        )
        # Every block from the transaction's block through the highest
        # confirmed block is confirmed: the only pending block the chain
        # ever carries is its tip, which the slice stops before.
        headers = [
            self._header_entry(candidate)
            for candidate in self.store.chain[
                block.height : finalized_block.height + 1
            ]
        ]
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError(
                "no audit signer available for finalized receipt"
            )
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        finality = {
            "finalized": finalized,
            "tip": tip,
            "auth": auth,
        }
        return 200, {
            "receipt": self._transaction_receipt(
                tx, STATUS_CONFIRMED, block.height, block.block_hash, index
            ),
            "proof": proof,

            "proofs": proofs,
            "auth": auth,
        }

def confirmed_balance(self, account: str) -> int:
    """Balance from confirmed blocks only."""
    entry = self.store.accounts.get(account)
    if entry is None:
        return self.initial_balance
    return self.initial_balance + entry["received"] - entry["sent"]

def reported_balance(self, account: str) -> int:
    """Confirmed balance minus spends sitting in the pending tip block.

    Pending-block credits are not counted: unconfirmed income can still
    be rolled back, so it must not inflate the reported balance.
    """
    balance = self.confirmed_balance(account)
    tip = self.store.tip()
    if tip.status == STATUS_PENDING:
        for tx in tip.transactions:
            if tx.sender == account:
                balance -= tx.amount
    return balance

def available_balance(self, account: str) -> int:
    """Reported balance minus amounts already committed in the mempool.

    Pending credits (mempool or unconfirmed block) are deliberately not
    counted, so a sequence of submissions cannot spend money that has not
    been confirmed yet.
    """
    balance = self.reported_balance(account)
    for tx in self.store.pending.values():
        if tx.sender == account:
            balance -= tx.amount
    return balance

# -- fork candidates -----------------------------------------------------

@staticmethod
def _fork_summary(blocks: list) -> dict:
    """Public fork descriptor S: tip_hash, height, length, status."""
    tip = blocks[-1]
    return {

def mine_block(self) -> tuple[int, dict]:
    """Pack all pending transactions (ascending tx_id) into a pending block.

    Only allowed when the chain tip is confirmed; the new block becomes
    the pending tip until it is confirmed or rolled back.
    """
    with self.store.lock:
        if self.store.tip_is_pending():
            return 409, {"error": "tip block is pending confirmation"}
        if not self.store.pending:
            return 409, {"error": "no pending transactions"}
        ordered = sorted(self.store.pending.values(), key=lambda tx: tx.tx_id)
        block = Block.create(
            height=self.store.next_height(),
            prev_hash=self.store.tip_hash(),
            transactions=ordered,
            status=STATUS_PENDING,
        )
        self.store.chain.append(block)
        removed = [self.store.pending.pop(tx.tx_id) for tx in ordered]
        # First creation of this pending block: one block_mined event
        # carrying the block's ascending in-block transaction order.
        self.store.append_audit_event(
            EVENT_BLOCK_MINED,
            {
                "height": block.height,
                "block_hash": block.block_hash,
                "merkle_root": block.merkle_root,
                "transaction_ids": [tx.tx_id for tx in ordered],
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Undo the in-memory block and its event so nothing
            # un-persisted is visible.
            self.store.chain.pop()
            self.store.pending.update({tx.tx_id: tx for tx in removed})
            self.store.truncate_audit_events(1)
            raise
    return 201, {
        "height": block.height,
        "block_hash": block.block_hash,
        "merkle_root": block.merkle_root,
        "status": block.status,
    }

def get_block(self, height: object) -> tuple[int, dict]:
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        return 200, block.to_summary()

def get_block_status(self, height: object) -> tuple[int, dict]:
    """GET /v1/blocks/{height}/status -> {height, status}; 404 if unknown."""
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        return 200, {"height": block.height, "status": block.status}

def confirm_block(self, height: object) -> tuple[int, dict]:
    """Confirm a pending tip block.

    Only a pending chain tip whose parent is confirmed can be confirmed.
    Confirming an already-confirmed block is idempotent (200); every
    other case — unknown or malformed height, non-tip pending block —
    returns 409.
    """
    height_int = _parse_height(height)
    with self.store.lock:
        if height_int is None:
            return 409, {"error": "block cannot be confirmed"}
        block = self.store.block_at(height_int)
        if block is None:
            return 409, {"error": "block cannot be confirmed"}
        if block.status == STATUS_CONFIRMED:
            # Idempotent re-confirm.
            return 200, {"height": block.height, "status": STATUS_CONFIRMED}
        if block is not self.store.tip():
            return 409, {"error": "only the chain tip can be confirmed"}
        parent = self.store.chain[-2] if len(self.store.chain) >= 2 else None
        if parent is None or parent.status != STATUS_CONFIRMED:
            return 409, {"error": "previous block is not confirmed"}
        block.status = STATUS_CONFIRMED
        # First confirmation of the pending tip: one block_confirmed
        # event; the idempotent re-confirm above appends nothing.
        self.store.append_audit_event(
            EVENT_BLOCK_CONFIRMED,
            {"height": block.height, "block_hash": block.block_hash},
        )
        try:
            self.store.save()
        except BaseException:
            block.status = STATUS_PENDING
            self.store.truncate_audit_events(1)
            raise
        return 200, {"height": block.height, "status": STATUS_CONFIRMED}

def rollback_block(self, height: object) -> tuple[int, dict]:
    """Roll back a pending tip block: delete it and restore its transactions.

    Unknown or malformed heights (including an already-rolled-back
    height) return 404; a confirmed block or a non-tip block returns 409.
    """
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status == STATUS_CONFIRMED:
            return 409, {"error": "confirmed block cannot be rolled back"}
        if block is not self.store.tip():
            return 409, {"error": "only the chain tip can be rolled back"}
        pending_before = set(self.store.pending)
        rolled_back = self.store.rollback_tip()
        # Record exactly the transactions that actually returned to the
        # mempool (rollback_tip de-duplicates ids already present), in the
        # block's ascending in-block order.
        restored_ids = [
            tx.tx_id
            for tx in rolled_back.transactions
            if tx.tx_id not in pending_before
        ]
        self.store.append_audit_event(
            EVENT_BLOCK_ROLLED_BACK,
            {
                "height": rolled_back.height,
                "block_hash": rolled_back.block_hash,
                "transaction_ids": restored_ids,
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Restore the block and drop only the mempool entries we added.
            self.store.chain.append(rolled_back)
            for tx_id in list(self.store.pending):
                if tx_id not in pending_before:
                    del self.store.pending[tx_id]
            self.store.truncate_audit_events(1)
            raise
        return 200, {"height": rolled_back.height, "status": "rolled_back"}

def get_proof(self, height: object, tx_id: object) -> tuple[int, dict]:
    """Return a Merkle inclusion proof for tx_id at the given height.

    Returns 404 for an unknown height, a malformed height/tx_id, or a
    transaction absent from that block. Proofs are only issued for
    confirmed blocks; a pending block returns 409.
    """

"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str
    # None marks a legacy transfer signed over crypto.canonical_message; a
    # non-boolean non-negative integer marks a sequenced transfer signed over
    # crypto.sequenced_message and bound to the sender's per-account sequence.
    nonce: int | None = None

    @property
    def message(self) -> bytes:
        if self.nonce is None:
            return crypto.canonical_message(self.sender, self.recipient, self.amount)
        return crypto.sequenced_message(
            self.sender, self.recipient, self.amount, self.nonce
        )

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    @property
    def sequenced(self) -> bool:
        return self.nonce is not None

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        result = {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
        }
        # The nonce is present only on sequenced transfers, so a legacy
        # transaction keeps its exact five-field wire shape.
        if self.nonce is not None:
            result["nonce"] = self.nonce
        result["tx_id"] = self.tx_id
        return result

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        # A present nonce must already be a non-boolean, non-negative integer
        # — never a coercible string, float, bool or negative. A missing key
        # denotes a legacy transfer and stays None.
        nonce = data.get("nonce")
        if nonce is not None and (
            isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0
        ):
            raise ValueError("transaction nonce must be a non-negative integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
            nonce=nonce,
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

        source, request_id, expires_at, anchor, blocks, tip
    )
    return hashlib.sha256(message + signature.encode("ascii")).hexdigest()


def valid_idempotency_key(value: object) -> bool:
    """Validate an Idempotency-Key header value.

    A key is 1..128 visible ASCII characters (0x21..0x7E): no spaces, tabs or
    other control characters.
    """
    if not isinstance(value, str):
        return False
    if not (IDEMPOTENCY_KEY_MIN <= len(value) <= IDEMPOTENCY_KEY_MAX):
        return False
    return all(0x21 <= ord(char) <= 0x7E for char in value)


def canonical_request_body(body: object) -> str | None:
    """Canonical JSON text of a parsed request body.

    Key order and insignificant whitespace never matter: the parsed value is
    re-serialized with sorted keys and compact separators. An empty body is
    the empty string. Returns ``None`` when no stable fingerprint can be
    formed (a non-JSON value that does not round-trip deterministically).
    """
    if body is None:
        return ""
    try:
        return json.dumps(
            body, sort_keys=True, ensure_ascii=False, separators=(",", ":")
        )
    except (TypeError, ValueError):
        return None


def request_fingerprint(method: str, target: str, canonical_body: str) -> str:
    """Stable fingerprint of method, the full request target and the body.

    The fingerprint is the SHA-256 of ``METHOD \\0 TARGET \\0 CANONICAL_BODY``
    where ``TARGET`` is the request line's full target (path plus query) and
    ``CANONICAL_BODY`` is :func:`canonical_request_body` output.
    """
    digest = hashlib.sha256()
    digest.update(method.encode("ascii"))
    digest.update(b"\x00")
    digest.update(target.encode("utf-8"))
    digest.update(b"\x00")
    digest.update(canonical_body.encode("utf-8"))
    return digest.hexdigest()


class SyncSummary:
    """Resolve the frozen tip descriptor (height/length/status) for a synced
    candidate during recovery, from either a surviving fork or a canonical
    chain prefix.
    """

    @staticmethod
    def from_blocks_raw(tip_hash: str, blocks_raw: list[dict]) -> dict | None:
        """Build the descriptor for an already-resolved raw block list whose
        last block hash must equal ``tip_hash``.
        """
        if not blocks_raw:
            return None
        tip = blocks_raw[-1]
        if tip.get("block_hash") != tip_hash:
            return None
        return {
            "height": tip["height"],
            "length": len(blocks_raw),
            "status": tip["status"],
        }

    @classmethod
    def from_locations(
        cls,
        tip_hash: str,
        forks: dict[str, list[Block]],
        canonical_chain: list[Block],
    ) -> dict | None:
        """Resolve a descriptor among surviving forks first, then canonical
        blocks (the delivered fork may since have been adopted).
        """
        fork = forks.get(tip_hash)
        if fork is not None:
            return cls.from_blocks_raw(tip_hash, [block.to_dict() for block in fork])
        prefix: list[dict] = []
        for block in canonical_chain:
            prefix.append(block.to_dict())
            if block.block_hash == tip_hash:
                return cls.from_blocks_raw(tip_hash, prefix)
        return None


class StateRecoveryError(ValueError):
    """Raised when no usable on-disk state can be recovered on startup.

    Carries the candidate ``path`` that failed and a human-readable ``reason``
    so callers can report (or catch) the failure explicitly. The exception is a
    ``ValueError`` subclass, so older callers expecting ``ValueError`` on a
    corrupt state file keep working.
    """

    def __init__(self, path: str, reason: str) -> None:
        self.path = path
        self.reason = reason
        super().__init__(f"cannot recover ledger state from {path}: {reason}")


